--[[
	PluginActions  -  DISABLED under the P-prefix leader policy

	A no-op: no Studio PluginActions are registered. Studio fires PluginAction.Triggered without
	the leader key held, so a Studio-bound shortcut would get around the leader.
	  register(plugin, ctx, wiring, dispatcher) -> {stop}
]]

local PluginActions = {}

function PluginActions.register(_plugin, _ctx, _wiring, _dispatcher)
	return {stop = function() end}
end

return PluginActions

