-- BuildPropertiesContainer  -  Properties panel section for Container, built by BuildProperties.

local W = require(script.Parent.Widgets)
local BuildPropertiesContainer = {}

function BuildPropertiesContainer.buildSection(scroll, refs)
	-- A row with one of these gets an asterisk that opens "Apply to", the kinds it acts on
	-- (TypeDataContainer.APPLY_KINDS; PropertyInputsContainer wires it). Only what is spawned has a
	-- spread; a mesh has no light property. A carried Force and its Reactors take only the time.
	local applyTo = { kind = "apply-to", kinds = { "Emitter", "Mesh", "Beam", "Trail" } }
	local applyToTimed = { kind = "apply-to", kinds = { "Emitter", "Mesh", "Beam", "Trail", "Reactor" } }
	local applyToSpawned = { kind = "apply-to", kinds = { "Emitter", "Mesh" } }
	local applyToLit = { kind = "apply-to", kinds = { "Emitter", "Beam", "Trail" } }
	-- Part is plain parts, decals and Models' parts; Effect is rigs, Mattes, Highlights, Distortions,
	-- ImageLabels and lights.
	local applyToFaded = { kind = "apply-to", kinds = { "Emitter", "Mesh", "Beam", "Trail", "Part", "Effect" } }
	local containerDefs = {
		{name = "Emission", rows = {
			{key="Enabled",  label="Enabled", type="toggle"},
			{key="EmitMode", label="Type", type="dropdown", options={"Auto","Burst"}, default="Auto"},
			{key="Rate",     label="Rate", type="input", default="2"},
			{key="Lifetime", label="Lifetime", type="input", default="1, 1", placeholder="min, max"},
			-- The options are TypeDataContainer.MODES: the runtime compares the stored text.
			{key="Mode",     label="Mode", type="dropdown", options={"Absolute","Relative","Relative Lifetime","Relative Span"}, default="Absolute"},
		}},
		-- "x" rows multiply each emitter's value (1 leaves it), "+" rows add to it (0 leaves it).
		-- Spread is one row for both axes (DriveSpreadX / DriveSpreadY). White Color leaves it alone.
		{name = "Drive", rows = {
			{key="DriveRate",           label="Rate x", type="graph", config=applyTo},
			{key="DriveScale",          label="Scale x", type="graph", config=applyTo},
			{key="DriveTimescale",      label="Timescale x", type="graph", config=applyToTimed},
			{key="DriveBrightness",     label="Brightness x", type="graph", config=applyTo},
			{key="DriveSpread",         label="Spread +deg", type="axis_graph_select", axes={"X","Y"}, config=applyToSpawned},
			{key="DriveLightInfluence", label="Light Infl. +", type="graph", config=applyToLit},
			{key="DriveLightEmission",  label="Light Emis. +", type="graph", config=applyToLit},
			{key="DriveColor",          label="Color", type="color", config=applyTo},
			{key="ColorMode",           label="Color Mode", type="dropdown", options={"Recolor","Colorize","Shift","Tint"}, default="Recolor"},
			-- Fades the whole group, nested Containers too: 0 leaves it, 1 hides it. "Transparency" does not
			-- fit beside the asterisk.
			{key="DriveTransparency",   label="Transp.", type="graph", config=applyToFaded},
		}},
		{name = "Advanced", collapsed = true, rows = {
			{key="EmitParent", label="Emit Into", type="path", config={kind="instance-picker", objectValue="EmitParent", acceptAnyInstance=true}},
		}},
	}
	refs.ContainerSection, refs.Container = W.buildTypeSection(scroll, "Containers", containerDefs, 3)
	refs.ContainerSection.Visible = false
end

return BuildPropertiesContainer
